# ================= Helpers continued =================
def shell_escape(s):
    safe="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_./-"
    if s=="":
        return "''"
    for c in s:
        if c not in safe:
            return "'"+s.replace("'", "'\\''")+"'"
    return s

class ParseError(Exception):
    def __init__(self, msg, filename, lineno, line_text=None, col=None):
        super().__init__(msg)
        self.msg=msg
        self.filename=filename
        self.lineno=lineno
        self.line_text=line_text
        self.col=col
    def format(self):
        base=f"ninja: error: {self.filename}:{self.lineno}: {self.msg}\n"
        if self.line_text is not None and self.col is not None:
            base+=self.line_text+"\n"
            base+=" "*self.col+"^ near here\n"
        else:
            base+="\n"
        return base

class BadEscapeError(Exception):
    def __init__(self, pos):
        self.pos=pos
class VersionCaretError(Exception):
    def __init__(self, pos):
        self.pos=pos

def version_at_least(v, req):
    def parse(s):
        m=re.match(r'^\s*(\d+)(?:\.(\d+))?(?:\.(\d+))?', s)
        if not m:
            return None
        major=int(m.group(1))
        minor=int(m.group(2)) if m.group(2) else 0
        patch=int(m.group(3)) if m.group(3) else 0
        return (major,minor,patch)
    pv=parse(v); pr=parse(req)
    if pv is None or pr is None:
        return False
    return pv>=pr

def expand_string(s, scope, version):
    res=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c!='$':
            res.append(c); i+=1
        else:
            if i+1>=n:
                raise BadEscapeError(i)
            nxt=s[i+1]
            if nxt=='$':
                res.append('$'); i+=2
            elif nxt==' ':
                res.append(' '); i+=2
            elif nxt==':':
                res.append(':'); i+=2
            elif nxt=='^':
                if version is None or not version_at_least(version, "1.14"):
                    raise VersionCaretError(i)
                res.append('\n'); i+=2
            elif nxt=='\n':
                i+=2
                while i<n and s[i] in (' ','\t'):
                    i+=1
            elif nxt=='{':
                j=s.find('}', i+2)
                if j==-1:
                    raise BadEscapeError(i)
                varname=s[i+2:j]
                if varname=="" or not re.match(r'^[A-Za-z0-9_.\-]+$', varname):
                    # Actually inside {} allow dot? Yes. But check: ${} empty already handled as empty -> bad. For ${a!}, ! not allowed -> bad.
                    raise BadEscapeError(i)
                # For ${}, lookup: allow dot? Yes. So varname can contain dot.
                # But need to validate? If varname contains invalid chars like !, already bad.
                # Also need to check that varname matches allowed? For ${a:b}? : not allowed -> bad.
                # Our regex allows dot, dash, alphanum, underscore. Good. What about :? Not allowed -> bad, correct.
                val=scope.get(varname, "")
                # Note: scope may have flat merged? We'll pass flat dict.
                res.append(val)
                i=j+1
            elif re.match(r'[A-Za-z0-9_-]', nxt):
                j=i+1
                while j<n and re.match(r'[A-Za-z0-9_-]', s[j]):
                    j+=1
                varname=s[i+1:j]
                val=scope.get(varname, "")
                res.append(val)
                i=j
            else:
                raise BadEscapeError(i)
    return ''.join(res)

def expand_with_scope(raw, flat_scope, filename, lineno, line_text, col_offset, version):
    try:
        return expand_string(raw, flat_scope, version)
    except BadEscapeError as e:
        raise ParseError("bad $-escape (literal $ must be written as $$)", filename, lineno, line_text, col_offset+e.pos)
    except VersionCaretError as e:
        raise ParseError("using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", filename, lineno, line_text, col_offset+e.pos)

