def tool_targets(state, scope_stack, opts, args):
    if len(args)==0:
        mode='default'
    elif args[0]=='all':
        if len(args)>1:
            pass
        outs=[]
        for e in state.edges:
            for o in e.outputs+e.implicit_outputs:
                r=e.rule_name
                outs.append(f"{o}: {r}\n")
        # Sort? Original for assets all gave main.o, helper.o, app in edge order? Edges order: main.o (0), helper.o (1), app (2). Output was main.o, helper.o, app in that order. Good (edge order, not sorted).
        # For our test with a,b,c (a,b,c where c depends on b), all gave a,b,c in edge order (a,b,c). Good.
        for line in outs:
            sys.stdout.write(line)
        return 0
    elif args[0]=='rule':
        if len(args)<2:
            # rule with no name: list source files (leaves)? Earlier "targets rule" with no name gave main.c, helper.c (sources). Good.
            # How to compute leaves? All inputs that are not outputs?
            all_outs=set(get_all_outputs(state))
            leaves=set()
            for e in state.edges:
                for inp in e.inputs+e.implicit+e.order_only:
                    if inp not in all_outs:
                        leaves.add(inp)
            for l in sorted(leaves):
                sys.stdout.write(f"{l}\n")
            return 0
        rulename=args[1]
        outs=[]
        for e in state.edges:
            if e.rule_name==rulename:
                for o in e.outputs+e.implicit_outputs:
                    outs.append(o+"\n")
