def tool_rules_fixed(state, scope_stack, opts, args):
    show_desc=False
    for a in args:
        if a=='-d':
            show_desc=True
        else:
            sys.stdout.write("usage: ninja -t rules [options]\n\noptions:\n  -d     also print the description of the rules\n")
            sys.stderr.write(f"rules: invalid option -- '{a}'\n")
            return 1
    names=sorted(state.rules.keys())
    names.append('phony')
    for n in names:
        if show_desc and n in state.rules and 'description' in state.rules[n].vars:
            raw=state.rules[n].vars['description']
            exp=""
            i=0
            L=len(raw)
            while i<L:
                if raw[i]=='$' and i+1<L:
                    nxt=raw[i+1]
                    if nxt=='$':
                        exp+='$$'
                        i+=2
                    elif nxt=='{':
                        j=raw.find('}',i+2)
                        if j==-1:
                            exp+=raw[i:]
                            break
                        else:
                            exp+=raw[i:j+1]
                            i=j+1
                    elif nxt in (' ',';',':','^'):
                        exp+=raw[i:i+2]
                        i+=2
                    elif nxt.isalnum() or nxt in ('_','-'):
                        j=i+1
                        while j<L and (raw[j].isalnum() or raw[j] in ('_','-')):
